insert into public.game_content (game_id, language, volume, level, content, is_published)
values
(
  'stories',
  'en',
  1,
  5,
  $stories_en_level_5$
  [
    {"title":"The Clockmaker and Time","story":"Mr. Ernest was a clockmaker known for repairing the most complicated clocks. One day, a woman arrived with a clock that had belonged to her father. Its mechanism was intact, but the hands did not move. Ernest examined it for hours until he understood that the clock did not need repairing: it was designed to work only when someone turned a small key. The woman explained that her father used it to remember that every day should begin with a decision. Ernest returned the clock and said that some objects hold something more valuable than their function.","question":"What did Ernest mean when he said some objects hold something more valuable than their function?","correct":"Memories and meaning can be more important than the object itself","options":["Old clocks should never be repaired","Memories and meaning can be more important than the object itself","All clocks need a key","Machines are more valuable than people"],"emoji":"⌚"},
    {"title":"The Island of Roads","story":"An island had two villages separated by a mountain. For years, residents exchanged goods using a long road around the mountain. A young engineer suggested building a tunnel, but merchants feared losing their transportation businesses. Instead of insisting, the engineer organized meetings and discovered that many transporters also needed to reach the other village faster. He suggested that they participate in building and managing the new route. Finally, the tunnel became an opportunity for both villages.","question":"What strategy helped the engineer overcome the initial opposition?","correct":"He listened to the merchants' interests and included them in the project","options":["He built the tunnel without telling anyone","He listened to the merchants' interests and included them in the project","He forced everyone to use the tunnel","He canceled the meetings"],"emoji":"⛰️"},
    {"title":"The Garden of Decisions","story":"At a school, each class had a small space to grow plants. The fifth-grade group received seeds from different species, but they only had enough water to care for part of the garden. Some wanted to choose the most colorful flowers, while others preferred plants that provided food for insects. The teacher did not decide for them. She asked them to research which species needed less water and which helped the ecosystem most. After comparing the information, they chose a combination of hardy plants that attracted butterflies and bees.","question":"What was the most important criterion in the group's final decision?","correct":"Balancing water conservation with benefits for the ecosystem","options":["Choosing only the prettiest flowers","Planting every seed without researching","Balancing water conservation with benefits for the ecosystem","Choosing the fastest-growing plants"],"emoji":"🦋"},
    {"title":"The Invisible Library","story":"In a city, a library began receiving fewer and fewer visitors. Its books were still interesting, but many residents thought only people who wanted to study could enter. The new librarian decided to change that idea. She organized storytelling sessions, object-repair workshops, and spaces for sharing experiences. She also invited older residents to tell stories about the neighborhood. Months later, the library was full of visitors who were looking not only for books, but also for opportunities to learn from one another. The librarian understood that a library could be much more than a place where pages are kept.","question":"What is the main idea of the story?","correct":"A library can also be a place for community and shared learning","options":["Books are no longer important","A library can also be a place for community and shared learning","Older people should run all libraries","Workshops should replace reading"],"emoji":"📚"},
    {"title":"The Mountain's Last Message","story":"A group of explorers found an ancient inscription on a mountain: 'The shortest path does not always lead to the right destination.' Some thought it was a warning about dangerous trails. Others believed it referred to an ancient treasure. While they argued, one explorer noticed that the map showed two routes: a short one crossing unstable ground and a longer one passing beside a river where travelers could rest. They chose the second route. When they arrived, they discovered that the supposed treasure was a shelter built for travelers. They understood that the true value of the message was learning to choose carefully, not simply arriving first.","question":"Which interpretation best represents the mountain's message?","correct":"Decisions should consider their consequences, not just speed","options":["Always choose the longest path","Treasures never exist","Decisions should consider their consequences, not just speed","Old maps cannot be trusted"],"emoji":"🏔️"}
  ]
  $stories_en_level_5$::jsonb,
  true
),
(
  'stories',
  'es',
  1,
  5,
  $stories_es_level_5$
  [
    {"title":"El relojero y el tiempo","story":"Don Ernesto era un relojero conocido por reparar los relojes más complicados. Un día llegó una mujer con un reloj que había pertenecido a su padre. El mecanismo estaba intacto, pero las agujas no se movían. Ernesto lo examinó durante horas hasta comprender que el reloj no necesitaba una reparación: estaba diseñado para funcionar únicamente cuando alguien giraba una pequeña llave. La mujer explicó que su padre lo usaba para recordar que cada día debía comenzar con una decisión. Ernesto devolvió el reloj y le dijo que algunos objetos guardan algo más valioso que su funcionamiento.","question":"¿Qué quiso expresar Ernesto al decir que algunos objetos guardan algo más valioso que su funcionamiento?","correct":"Que los recuerdos y significados pueden ser más importantes que el objeto en sí","options":["Que los relojes antiguos no deben repararse","Que los recuerdos y significados pueden ser más importantes que el objeto en sí","Que todos los relojes necesitan una llave","Que las máquinas son más valiosas que las personas"],"emoji":"⌚"},
    {"title":"La isla de los caminos","story":"Una isla tenía dos pueblos separados por una montaña. Durante años, sus habitantes intercambiaban productos utilizando un camino largo que rodeaba la montaña. Un joven ingeniero propuso construir un túnel, pero los comerciantes temían perder sus negocios de transporte. En vez de insistir, el ingeniero organizó reuniones y descubrió que muchos transportistas también necesitaban llegar más rápido al otro pueblo. Propuso que ellos participaran en la construcción y administraran el nuevo recorrido. Finalmente, el túnel se convirtió en una oportunidad para ambos pueblos.","question":"¿Qué estrategia permitió que el ingeniero superara la oposición inicial?","correct":"Escuchó los intereses de los comerciantes y los integró al proyecto","options":["Construyó el túnel sin avisar","Escuchó los intereses de los comerciantes y los integró al proyecto","Obligó a todos a utilizar el túnel","Canceló las reuniones"],"emoji":"⛰️"},
    {"title":"El jardín de las decisiones","story":"En una escuela, cada curso tenía un pequeño espacio para cultivar plantas. El grupo de quinto grado recibió semillas de distintas especies, pero solo tenía agua suficiente para cuidar una parte del jardín. Algunos querían elegir las flores más coloridas, mientras otros preferían plantas que dieran alimento a los insectos. La maestra no decidió por ellos. Les pidió investigar qué especies necesitaban menos agua y cuáles ayudaban más al ecosistema. Después de comparar la información, eligieron una combinación de plantas resistentes que atraían mariposas y abejas.","question":"¿Qué criterio fue más importante para que el grupo tomara su decisión final?","correct":"Equilibrar el cuidado del agua con el beneficio para el ecosistema","options":["Elegir solamente las flores más bonitas","Plantar todas las semillas sin investigar","Equilibrar el cuidado del agua con el beneficio para el ecosistema","Escoger las plantas que crecían más rápido"],"emoji":"🦋"},
    {"title":"La biblioteca invisible","story":"En una ciudad, una biblioteca comenzó a recibir cada vez menos visitantes. Sus libros seguían siendo interesantes, pero muchos habitantes pensaban que solo podían entrar quienes querían estudiar. La nueva bibliotecaria decidió cambiar esa percepción. Organizó encuentros de narración, talleres de reparación de objetos y espacios para compartir experiencias. También invitó a personas mayores a contar historias del barrio. Meses después, la biblioteca estaba llena de visitantes que no solo buscaban libros, sino también aprender unos de otros. La bibliotecaria comprendió que una biblioteca podía ser mucho más que un lugar donde se guardan páginas.","question":"¿Cuál es la idea principal que transmite el cuento?","correct":"Una biblioteca también puede ser un espacio de encuentro y aprendizaje comunitario","options":["Los libros ya no son importantes","Una biblioteca también puede ser un espacio de encuentro y aprendizaje comunitario","Las personas mayores deben dirigir las bibliotecas","Los talleres deben reemplazar la lectura"],"emoji":"📚"},
    {"title":"El último mensaje de la montaña","story":"Un grupo de exploradores encontró una inscripción antigua en una montaña: 'El camino más corto no siempre conduce al destino correcto'. Algunos pensaron que era una advertencia sobre los senderos peligrosos. Otros creyeron que se refería a un antiguo tesoro. Mientras discutían, una exploradora observó que el mapa mostraba dos rutas: una corta que atravesaba una zona inestable y otra más larga que pasaba junto a un río y permitía descansar. Eligieron la segunda. Al llegar, descubrieron que el supuesto tesoro era un refugio construido para viajeros. Comprendieron que el verdadero valor del mensaje estaba en aprender a elegir con cuidado, no simplemente en llegar primero.","question":"¿Qué interpretación representa mejor el mensaje de la montaña?","correct":"Las decisiones deben considerar sus consecuencias y no solo la rapidez","options":["Siempre hay que elegir el camino más largo","Los tesoros nunca existen","Las decisiones deben considerar sus consecuencias y no solo la rapidez","Los mapas antiguos no son confiables"],"emoji":"🏔️"}
  ]
  $stories_es_level_5$::jsonb,
  true
)
on conflict (game_id, language, volume, level) do nothing;
